def apply(s):
    for old,new in CHANGES:
        if s.count(old)!=1: raise ValueError("TV choice anchor mismatch")
        s=s.replace(old,new,1)
    return s + "\n# Local TV sound choice: takes effect on next plugin start.\nimport xml.etree.ElementTree as _tv_choice_et\n_tv_choice_skin = _tv_choice_et.fromstring(EmbyFlowAdvancedSettingsNeon.skin)\nfor _node in _tv_choice_skin:\n    if _node.get('name') == 'middle_help':\n        _node.set('position', '715,730')\n        _node.set('size', '490,35')\n_tv_choice_et.SubElement(_tv_choice_skin, 'eLabel', {\n    'text': 'TV-Ton im Plugin (ab nächstem Start)', 'position': '715,770',\n    'size': '490,32', 'font': 'Regular;22', 'foregroundColor': '#eeeeee',\n    'transparent': '1'})\n_tv_choice_et.SubElement(_tv_choice_skin, 'widget', {\n    'name': 'tv_sound_value', 'zPosition': '6', 'position': '715,805', 'size': '490,35',\n    'font': 'Regular;24', 'foregroundColor': '#b54ce8',\n    'backgroundColor': '#081424', 'transparent': '0'})\nEmbyFlowAdvancedSettingsNeon.skin = _tv_choice_et.tostring(_tv_choice_skin, encoding='unicode')\n\n# EMBYFLOW_TV_SOUND_LEFT_LAYOUT\n_tv_left_skin = _tv_choice_et.fromstring(EmbyFlowAdvancedSettingsNeon.skin)\nfor node in _tv_left_skin:\n    name = node.get('name', '')\n    text = node.get('text', '')\n    pos = node.get('position', '')\n    if name == 'tv_sound_value':\n        node.attrib.update(position='82,550', size='466,38', font='Bold;22', foregroundColor='#36d4e8', backgroundColor='#0A1627', zPosition='6', valign='center')\n    elif text.startswith('TV-Ton im Plugin'):\n        node.attrib.update(text='TV-Ton im Plugin', position='75,500', size='470,34')\n    elif text == 'Bibliothekssynchronisation':\n        node.set('position', '75,630')\n    elif name == 'sync_value':\n        node.attrib.update(position='82,681', size='466,54')\n    elif node.tag == 'eLabel' and pos == '65,547':\n        node.set('position', '65,670')\n    elif name == 'left_help':\n        node.attrib.update(position='75,755', size='470,75')\n    elif name == 'middle_help':\n        node.attrib.update(position='715,746', size='470,72')\n_tv_choice_et.SubElement(_tv_left_skin, 'eLabel', {'position':'65,537', 'size':'500,64', 'backgroundColor':'#0A1627'})\nEmbyFlowAdvancedSettingsNeon.skin = _tv_choice_et.tostring(_tv_left_skin, encoding='unicode')\n\ndef _tv_left_up(self):\n    order = (0, 6, 1, 2, 3, 4, 5)\n    self.focus = order[(order.index(self.focus) - 1) % len(order)]\n    self.refresh_all()\n\ndef _tv_left_down(self):\n    order = (0, 6, 1, 2, 3, 4, 5)\n    self.focus = order[(order.index(self.focus) + 1) % len(order)]\n    self.refresh_all()\n\n_TV_LEFT_TARGET = EmbyFlowAdvancedSettingsNeon._focus_target\n\ndef _tv_left_target(self):\n    if self.focus == 6:\n        return (48, 550)\n    if self.focus == 1:\n        return (48, 681)\n    return _TV_LEFT_TARGET(self)\n\nEmbyFlowAdvancedSettingsNeon.move_up = _tv_left_up\nEmbyFlowAdvancedSettingsNeon.move_down = _tv_left_down\nEmbyFlowAdvancedSettingsNeon._focus_target = _tv_left_target\n"
